  'الدخول غير بالكود (بحال Zoom): صيفط الكود للناس اللي بغيتي': ['Entrée uniquement avec un code (comme Zoom) : envoyez le code aux personnes de votre choix', 'Entry with a code only (like Zoom): send the code to the people you choose'],
  'وقت اللايف الجاي': ['Date et heure du prochain live', 'Date and time of the next live'],
  'حيد الموعد': ['Supprimer la date', 'Clear the date'],
  'نسخ الدعوة': ['Copier l’invitation', 'Copy the invitation'],
  'دعوة للايف: {room}': ['Invitation au live : {room}', 'Invitation to the live: {room}'],
  'الوقت: {when}': ['Date : {when}', 'When: {when}'],
